/**
 * Types and loader for the pooltool reference fixtures in
 * test/fixtures/pooltool/, generated by tools/reference/pooltool_fixtures.py
 * (schema documented there). Fixtures are reference data only: pooltool's
 * output, not pooltool code.
 */
import { readdirSync, readFileSync } from "node:fs"

export const FIXTURE_SCHEMA = 1
const DIR = new URL("../fixtures/pooltool/", import.meta.url)
const DIR_3D = new URL("../fixtures/pooltool3d/", import.meta.url)
const DIR_MATHAVAN = new URL("../fixtures/pooltool-mathavan/", import.meta.url)

export type Vec3 = [number, number, number]
/** [position, velocity, angular velocity]. */
export type Rvw = [Vec3, Vec3, Vec3]

/** pooltool motion states. */
export const MotionState = {
  stationary: 0,
  spinning: 1,
  sliding: 2,
  rolling: 3,
  pocketed: 4,
  airborne: 5,
  offTable: 6,
} as const

export interface BallParams {
  m: number
  R: number
  u_s: number
  u_r: number
  u_sp_proportionality: number
  u_b: number
  e_b: number
  e_t: number
  e_c: number
  f_c: number
  g: number
}

export interface BallState {
  rvw: Rvw
  s: number
}

export interface FixtureEvent {
  type:
    | "none"
    | "stick_ball"
    | "ball_ball"
    | "ball_linear_cushion"
    | "ball_circular_cushion"
    | "ball_pocket"
    | "ball_table"
    | "ball_off_table"
    | "spinning_stationary"
    | "rolling_stationary"
    | "rolling_spinning"
    | "sliding_rolling"
  time: number
  ids: string[]
  /** Post-event state of each ball involved. */
  states: Record<string, BallState>
}

export interface FixtureShot {
  name: string
  description: string
  balls: ({ id: string; params: BallParams } & BallState)[]
  cue: { ball: string; V0: number; phi: number; theta: number; a: number; b: number; specs: Record<string, unknown> }
  events: FixtureEvent[]
  final: Record<string, BallState>
}

export interface LinearCushion {
  id: string
  p1: Vec3
  p2: Vec3
  nose_radius: number
  direction: number
}

export interface FixtureFile {
  schema: number
  generator: { pooltool: string; commit: string; numpy: string }
  category: string
  description: string
  engine: { is_3d: boolean; resolver: Record<string, unknown> }
  table: {
    type: string
    specs: Record<string, number | string>
    linear: LinearCushion[]
    circular: { id: string; center: Vec3; radius: number }[]
    pockets: { id: string; center: Vec3; radius: number; depth: number }[]
  }
  shots: FixtureShot[]
}

/**
 * The 2D fixtures; with `threeD`, the ones from pooltool's 3D engine; with
 * "mathavan", 2D with Mathavan's ball-ball and cushion models.
 */
export function loadFixtures(set: boolean | "mathavan" = false): FixtureFile[] {
  const dir = set === "mathavan" ? DIR_MATHAVAN : set ? DIR_3D : DIR
  return readdirSync(dir)
    .filter((f) => f.endsWith(".json"))
    .sort()
    .map((f) => JSON.parse(readFileSync(new URL(f, dir), "utf8")) as FixtureFile)
}
